import json
import os
import statistics


class ResultsAnalyzerLite:
    def __init__(self):
        self.semantic_results = None
        self.parent_child_results = None

    def load_results(
        self,
        semantic_path: str = "results/results_semantic.json",
        parent_child_path: str = "results/results_parent-child.json",
    ):
        """Load evaluation results generated by eval.py."""
        with open(semantic_path, "r", encoding="utf-8") as f:
            self.semantic_results = json.load(f)

        with open(parent_child_path, "r", encoding="utf-8") as f:
            self.parent_child_results = json.load(f)

        print(
            f"Loaded {len(self.semantic_results)} semantic results"
        )
        print(
            f"Loaded {len(self.parent_child_results)} "
            "parent-child results"
        )

    @staticmethod
    def aggregate_metrics(results):
        """Aggregate metrics that are actually present in eval.py results."""
        metrics = [
            "hit_at_1",
            "hit_at_3",
            "mrr",
            "faithfulness",
            "answer_relevancy",
        ]

        aggregated = {}

        for metric in metrics:
            scores = [
                float(r[metric])
                for r in results
                if r.get(metric) is not None
            ]

            if not scores:
                continue

            aggregated[metric] = {
                "mean": statistics.mean(scores),
                "median": statistics.median(scores),
                "stdev": (
                    statistics.stdev(scores)
                    if len(scores) > 1
                    else 0.0
                ),
                "min": min(scores),
                "max": max(scores),
                "valid": len(scores),
                "total": len(results),
            }

        return aggregated

    def compare_strategies(self):
        """Compare semantic vs parent-child across available metrics."""
        semantic_agg = self.aggregate_metrics(self.semantic_results)
        parent_child_agg = self.aggregate_metrics(
            self.parent_child_results
        )

        comparison = {}

        for metric in semantic_agg.keys():
            if metric not in parent_child_agg:
                continue

            sem_mean = semantic_agg[metric]["mean"]
            pc_mean = parent_child_agg[metric]["mean"]

            diff = pc_mean - sem_mean
            diff_pct = (
                diff / sem_mean * 100
                if sem_mean != 0
                else 0.0
            )

            if diff > 0:
                winner = "parent-child"
            elif diff < 0:
                winner = "semantic"
            else:
                winner = "tie"

            comparison[metric] = {
                "semantic": sem_mean,
                "parent_child": pc_mean,
                "difference": diff,
                "difference_pct": diff_pct,
                "winner": winner,
                "semantic_stdev": semantic_agg[metric]["stdev"],
                "parent_child_stdev": (
                    parent_child_agg[metric]["stdev"]
                ),
                "semantic_valid": semantic_agg[metric]["valid"],
                "parent_child_valid": (
                    parent_child_agg[metric]["valid"]
                ),
            }

        return comparison

    @staticmethod
    def _average_available_metrics(result):
        """
        Calculate a query-level generation score using only metrics
        that are currently produced by eval.py.
        """
        values = []

        for metric in (
            "faithfulness",
            "answer_relevancy",
        ):
            value = result.get(metric)
            if value is not None:
                values.append(float(value))

        if not values:
            return None

        return sum(values) / len(values)

    def query_level_analysis(self):
        """Analyze which strategy performs better per query."""
        analysis = []

        # Match by query_id rather than relying on list ordering.
        semantic_by_id = {
            r.get("query_id"): r
            for r in self.semantic_results
        }
        parent_child_by_id = {
            r.get("query_id"): r
            for r in self.parent_child_results
        }

        common_ids = [
            query_id
            for query_id in semantic_by_id
            if query_id in parent_child_by_id
        ]

        for query_id in common_ids:
            sem_result = semantic_by_id[query_id]
            pc_result = parent_child_by_id[query_id]

            sem_avg = self._average_available_metrics(
                sem_result
            )
            pc_avg = self._average_available_metrics(
                pc_result
            )

            if sem_avg is None or pc_avg is None:
                continue

            if pc_avg > sem_avg:
                winner = "parent-child"
            elif sem_avg > pc_avg:
                winner = "semantic"
            else:
                winner = "tie"

            margin = abs(pc_avg - sem_avg)

            analysis.append(
                {
                    "query_id": query_id,
                    "query": sem_result.get("query", ""),
                    "semantic_score": sem_avg,
                    "parent_child_score": pc_avg,
                    "winner": winner,
                    "margin": margin,
                }
            )

        return analysis

    def generate_markdown_report(self):
        """Generate a detailed markdown comparison report."""
        comparison = self.compare_strategies()
        query_analysis = self.query_level_analysis()

        sem_wins = sum(
            1
            for qa in query_analysis
            if qa["winner"] == "semantic"
        )
        pc_wins = sum(
            1
            for qa in query_analysis
            if qa["winner"] == "parent-child"
        )
        ties = sum(
            1
            for qa in query_analysis
            if qa["winner"] == "tie"
        )

        total_queries = len(query_analysis)
        if total_queries:
            sem_pct = 100 * sem_wins / total_queries
            pc_pct = 100 * pc_wins / total_queries
        else:
            sem_pct = pc_pct = 0.0

        report = f"""# RAGBench Evaluation Report

## Executive Summary

This report compares **semantic chunking** vs
**parent-child chunking** using the metrics currently produced by
`eval.py`.

### Query-Level Generation Results

- Semantic Chunking wins: {sem_wins}/{total_queries}
  ({sem_pct:.1f}%)
- Parent-Child Chunking wins: {pc_wins}/{total_queries}
  ({pc_pct:.1f}%)
- Ties: {ties}/{total_queries}

---

## Metric-Level Comparison

| Metric | Semantic | Parent-Child | Difference | Winner |
|--------|----------|--------------|-----------|--------|
"""

        for metric, comp in comparison.items():
            report += (
                f"| {metric} | "
                f"{comp['semantic']:.3f} | "
                f"{comp['parent_child']:.3f} | "
                f"{comp['difference']:+.3f} "
                f"({comp['difference_pct']:+.1f}%) | "
                f"{comp['winner'].upper()} |\n"
            )

        report += """
---

## Detailed Metric Analysis

"""

        for metric, comp in comparison.items():
            report += f"""### {metric.replace('_', ' ').title()}

**Semantic Chunking**
- Mean: {comp['semantic']:.3f}
- Std Dev: {comp['semantic_stdev']:.3f}
- Valid: {comp['semantic_valid']}

**Parent-Child Chunking**
- Mean: {comp['parent_child']:.3f}
- Std Dev: {comp['parent_child_stdev']:.3f}
- Valid: {comp['parent_child_valid']}

**Difference:** {comp['difference']:+.3f}
({comp['difference_pct']:+.1f}%)
— **{comp['winner'].upper()}**

"""

        report += """
---

## Query-Level Results

The query-level generation score is the mean of the two generation
metrics currently available from `eval.py`:

- Faithfulness
- Answer Relevancy

### Queries Favoring Semantic Chunking

"""

        semantic_favored = sorted(
            [
                q
                for q in query_analysis
                if q["winner"] == "semantic"
            ],
            key=lambda x: x["margin"],
            reverse=True,
        )[:5]

        if semantic_favored:
            for i, qa in enumerate(
                semantic_favored, 1
            ):
                report += (
                    f"{i}. **{qa['query']}**\n"
                    f"   - Semantic: "
                    f"{qa['semantic_score']:.3f}\n"
                    f"   - Parent-Child: "
                    f"{qa['parent_child_score']:.3f}\n"
                    f"   - Margin: "
                    f"{qa['margin']:.3f}\n\n"
                )
        else:
            report += "No queries favored semantic chunking.\n\n"

        report += """
### Queries Favoring Parent-Child Chunking

"""

        pc_favored = sorted(
            [
                q
                for q in query_analysis
                if q["winner"] == "parent-child"
            ],
            key=lambda x: x["margin"],
            reverse=True,
        )[:5]

        if pc_favored:
            for i, qa in enumerate(
                pc_favored, 1
            ):
                report += (
                    f"{i}. **{qa['query']}**\n"
                    f"   - Parent-Child: "
                    f"{qa['parent_child_score']:.3f}\n"
                    f"   - Semantic: "
                    f"{qa['semantic_score']:.3f}\n"
                    f"   - Margin: "
                    f"{qa['margin']:.3f}\n\n"
                )
        else:
            report += "No queries favored parent-child chunking.\n\n"

        report += """
---

## Recommendations

### Retrieval

Use **Hit@1, Hit@3, and MRR** to evaluate retrieval quality.

- Hit@1 measures whether a relevant document is ranked first.
- Hit@3 measures whether a relevant document appears in the top three.
- MRR measures how highly the first relevant document is ranked.

### Generation

Use **Faithfulness** and **Answer Relevancy** to evaluate the
generated answer.

- Faithfulness measures whether answer claims are supported by the
  retrieved context.
- Answer Relevancy measures whether the answer addresses the question.

### Important

This analyzer intentionally does **not** report `context_relevancy`
or `context_recall` because the current `eval.py` does not produce
those fields.

---

## Limitations

- Evaluation is based on the available test queries.
- LLM-based generation scoring depends on the judge model.
- No human evaluation is included.
- The corpus is specialized in RAG concepts, so results may not
  generalize to other domains.
- The current analyzer only compares metrics actually generated by
  `eval.py`.

---

## Next Steps

1. Evaluate both strategies.
2. Compare retrieval and generation metrics.
3. Choose the strategy based on the intended use case.
4. Optionally add context-level metrics in `eval.py`.
5. Run on a larger corpus and test set.
6. Add human evaluation for validation.

---

## Summary Table

| Metric | Semantic | Parent-Child |
|--------|----------|--------------|
"""

        for metric in (
            "hit_at_1",
            "hit_at_3",
            "mrr",
            "faithfulness",
            "answer_relevancy",
        ):
            if metric not in comparison:
                continue

            comp = comparison[metric]
            report += (
                f"| {metric.replace('_', ' ').title()} | "
                f"{comp['semantic']:.3f} | "
                f"{comp['parent_child']:.3f} |\n"
            )

        report += """

---

Generated: RAGBench Lite
"""

        return report

    def save_report(self, report: str):
        """Save report to markdown file."""
        os.makedirs("results", exist_ok=True)

        with open(
            "results/EVALUATION_REPORT.md",
            "w",
            encoding="utf-8",
        ) as f:
            f.write(report)

        print(
            "Report saved to "
            "results/EVALUATION_REPORT.md"
        )

    def run_analysis(self):
        """Run full analysis and generate report."""
        print("\n" + "=" * 60)
        print("ANALYZING RESULTS")
        print("=" * 60 + "\n")

        comparison = self.compare_strategies()
        query_analysis = self.query_level_analysis()

        print(
            "Metric Comparison "
            "(Semantic vs Parent-Child):\n"
        )

        for metric, comp in comparison.items():
            print(f"{metric}:")
            print(
                f"  Semantic: "
                f"{comp['semantic']:.3f}"
            )
            print(
                f"  Parent-Child: "
                f"{comp['parent_child']:.3f}"
            )
            print(
                f"  Winner: "
                f"{comp['winner'].upper()} "
                f"({comp['difference_pct']:+.1f}%)\n"
            )

        report = self.generate_markdown_report()
        self.save_report(report)

        os.makedirs("results", exist_ok=True)

        with open(
            "results/query_analysis.json",
            "w",
            encoding="utf-8",
        ) as f:
            json.dump(
                query_analysis,
                f,
                indent=2,
            )

        print(
            "\n Query analysis saved to "
            "results/query_analysis.json"
        )
        print("\n Analysis complete!")
        print(
            "Check "
            "results/EVALUATION_REPORT.md "
            "for detailed findings"
        )


def main():
    analyzer = ResultsAnalyzerLite()

    try:
        analyzer.load_results()
        analyzer.run_analysis()
    except FileNotFoundError as e:
        print(f"Error: {e}")
        print(
            "Make sure to run eval.py first "
            "to generate both semantic and "
            "parent-child results files."
        )
    except KeyError as e:
        print(f"Missing metric in results: {e}")
        print(
            "The analyzer and eval.py metric "
            "schemas do not match."
        )


if __name__ == "__main__":
    main()